/* Transcribed from the four supplied blank workbook photos. No answer key supplied. */
const workbookData={"questions": [[1, "graft", 3, "解释为什么欧亚种类葡萄藤通常需要进行嫁接。", "Explain why vitis vinifera grape vines are generally grafted.", "roots", "chain", "回看根瘤蚜怎样损害根系、欧亚葡萄的抗性，以及抗性砧木如何使所需酿酒品种继续生长。按原因→影响→嫁接的结果写完整因果链。"], [1, "mediterranean", 6, "描述地中海气候。解释地中海气候对葡萄的生长有怎样的优势和挑战。", "Describe a Mediterranean climate. Explain the advantages and challenges of a Mediterranean climate for grape growing.", "climate", "text", "先描述夏季和冬季的温度、降雨特征，再把日照、成熟、真菌病害与缺水风险连接起来。避免只列优缺点而不说明原因。"], [1, "freeze", 4, "对于葡萄种植者来说，哪种天气灾害的危害最大：春季霜冻还是冬季冰冻？请给出你的理由。", "Which weather hazard has the most deleterious effect on the grape grower: spring frost or winter freeze? Gives reasons for your answer.", "needs", "text", "比较受损组织、当年产量、植株存活与恢复时间。结合冻害强度说明判断，区分当季新梢损伤和永久木质部分乃至整株死亡的长期后果。"], [1, "heat", 3, "描述天气过热和强烈的阳光对红葡萄酒最终风格的影响。", "Describe the effect of strong heat and sunlight on the final style of a red wine.", "needs", "text", "把葡萄糖分、酸度、风味的发展连接到酒精度、酸度与果味；注意题目中的“过热”，区分成熟促进与极端热害、缺水造成的成熟受阻。"], [2, "vsp", 5, "“新枝垂直分布形（VSP）”最适合什么样的气候？解释这样的架型如何提高葡萄的质量。", "What type of climate is VSP best suited to? Explain how VSP trellising can improve the quality of grapes.", "canopy", "text", "回看凉爽或温和条件下受光与通风的需求，解释新梢排列怎样改变遮阴、成熟和病害风险；炎热强光地区还需考虑果实遮护。"], [2, "bush", 4, "解释“灌木形/杯型（bush vine/goblet）”整形方式的优势和劣势。", "Explain the advantages and disadvantages of growing bush vines/goblet.", "training", "chain", "从树形、是否需要搭架、果实遮阴和机械作业条件出发，写明何种环境下成为优势或限制。不要把“便宜”或“品质好”作为无条件结论。"], [2, "harvest", 8, "你应该选择什么样的采收方式？为什么？", "What method of harvesting should you pick and why? (8 marks)", "harvest", "harvest", "逐行情境判断地形、规模、选择性与成本。山坡是否陡到限制机器需要说明；仅凭“Bordeaux AOP Rouge”不能推断唯一采收方式，也不能编造强制人工采收的法规。"], [2, "bordeaux", 3, "波尔多有着温和的海洋性气候。请列举出3个在葡萄生长过程中会遇到的问题（可以包含病害、虫害和天气灾害）。", "Bordeaux has a maritime climate. Please list 3 problems that may be encountered during the grape growing season (can include diseases, pest and weather hazards).", "health", "three", "列出三个不同且适合当地条件的问题，避免把同一病害换词重复计算。可回看潮湿相关的真菌病害及生长季天气风险。"]], "white": ["Chardonnay 霞多丽", "Riesling 雷司令", "Sauvignon Blanc 长相思", "Pinot Gris 灰皮诺", "Gewurztraminer 琼瑶浆", "Viognier 维欧尼", "Albariño 阿尔巴利诺", "Muscat/Moscato 麝香/莫斯卡托", "Chenin Blanc 白诗南", "Semillon 赛美蓉", "Furmint 福尔明", "Glera 格雷拉", "Cortese 柯蒂斯", "Garganega 卡尔卡耐卡", "Verdicchio 维蒂奇诺", "Fiano 菲亚诺"], "red": ["Zinfandel/Primitivo 金粉黛/普里米蒂沃", "Carménère 佳美娜", "Malbec 马尔贝克", "Pinotage 皮诺塔吉", "Gamay 佳美", "Montepulciano 蒙特普奇亚诺", "Barbera 巴贝拉", "Corvina 科维纳", "Sangiovese 桑娇维塞", "Nebbiolo 内比奥罗"]};
function workbookField(key,label,placeholder='用自己的话填写…'){
 const id='wb-'+key;return `<label class="wb-field" for="${id}"><span>${label}</span><textarea id="${id}" data-note="workbook-${key}" placeholder="${placeholder}">${safe(read(notesKey('workbook-'+key),''))}</textarea></label>`;
}
function workbookQuestion(q,i){const [session,id,marks,zh,en,unit,type,hint]=q;const key=`s${session}-${id}`;let fields='';
 if(type==='chain')fields=`<div class="wb-chain">${workbookField(key+'-a','因为有 A · Because of A',session===2?'灌木形/杯型整形方式的特点…':'原因…')}${workbookField(key+'-b','所以有 B 的影响 · Thus there is B','这一原因产生的影响…')}${workbookField(key+'-c','于是 C 的效果 · So it results in C',session===1?'欧亚种类葡萄藤通常需要嫁接…':'优势或劣势…')}</div>`;
 else if(type==='harvest')fields=['大批量的长相思 · Bulk Sauvignon Blanc','山坡的雷司令 · Hillside Riesling','贵腐葡萄 · Botrytis Grapes','波尔多干红 · Bordeaux AOP Rouge'].map((name,j)=>`<fieldset class="wb-harvest"><legend>${name}</legend><div class="wb-two">${workbookField(key+'-'+j+'-method','采摘方式 · Harvest Method')}${workbookField(key+'-'+j+'-reason','使用该采收方式的原因 · Reasons for harvest method')}</div></fieldset>`).join('');
 else if(type==='three')fields=[1,2,3].map(j=>workbookField(key+'-'+j,'问题 '+j)).join('');
 else fields=workbookField(key,'我的作答 · My answer','先作答，再展开复习提示。');
 return `<section class="quiz-card wb-question"><div class="eyebrow">QUESTION ${i+1} · ${marks} 分 / MARKS</div><h2>${zh}</h2><p class="wb-english" lang="en">${en}</p>${fields}<details class="recall"><summary>复习提示</summary><p>${hint}</p><a href="${session===1?'#lesson/':'#session2/'}${unit}">回看课程 ↗</a></details></section>`;
}
function workbookVarietyKeys(kind,index){return [0,1,2,3].map(j=>notesKey(`workbook-s1-${kind}-${index}-${j}`))}
function workbookVarietyValues(kind,index){return workbookVarietyKeys(kind,index).map(key=>{const v=read(key,'');return typeof v==='string'?v:''})}
function workbookVarietyMetaKey(kind,index){return `wset3-workbook-variety-${kind}-${index}`}
function workbookVarietyState(kind,index,values=workbookVarietyValues(kind,index)){
 const filled=values.filter(v=>v.trim()).length,meta=read(workbookVarietyMetaKey(kind,index),{});
 const status=filled===0?'empty':filled===4&&meta?.completed===true&&meta.fingerprint===JSON.stringify(values)?'complete':'draft';
 return {filled,status,label:{empty:'未填写',draft:'草稿',complete:'已完成'}[status],savedAt:meta?.savedAt||null};
}
function saveWorkbookVariety(kind,index,values,complete=false){
 if(!['white','red'].includes(kind)||!Number.isInteger(index)||!workbookData[kind][index]||values.length!==4||values.some(v=>typeof v!=='string'))return false;
 const keys=workbookVarietyKeys(kind,index);
 for(let j=0;j<4;j++)if(!save(keys[j],values[j]))return false;
 return save(workbookVarietyMetaKey(kind,index),{completed:complete&&values.every(v=>v.trim()),fingerprint:JSON.stringify(values),savedAt:Date.now()});
}
function workbookVarietyCounts(kind){const states=workbookData[kind].map((_,i)=>workbookVarietyState(kind,i));return {complete:states.filter(s=>s.status==='complete').length,draft:states.filter(s=>s.status==='draft').length,total:states.length}}
function workbookVarietyCard(kind,i){
 const labels=kind==='white'?['甜度 · Sweetness','酸度 · Acidity','酒体 · Body','味道特征 · Flavour Characteristic']:['颜色深度 · Colour intensity','酸度 · Acidity','单宁 · Tannins','味道特征 · Flavour Characteristic'];
 const state=workbookVarietyState(kind,i),name=workbookData[kind][i];
 return `<details class="wb-variety" data-variety-id="${kind}-${i}" data-kind="${kind}" data-index="${i}" data-status="${state.status}"><summary><span class="wb-variety-name">${name}</span><span class="wb-variety-meta"><span class="wb-variety-count">已填 ${state.filled} / 4</span><span class="wb-variety-status">${state.label}</span></span><span class="wb-variety-chevron" aria-hidden="true"></span></summary><div class="wb-variety-editor"><div class="wb-variety-fields">${labels.map((label,j)=>workbookField('s1-'+kind+'-'+i+'-'+j,label).replace(' data-note=',' data-variety-note data-note=')).join('')}</div><div class="wb-variety-actions"><button class="primary" type="button" data-variety-save="close">保存并收起</button>${kind==='red'&&i===workbookData.red.length-1?'':'<button class="wb-save-next secondary" type="button" data-variety-save="next">保存并下一项 →</button>'}</div><p class="wb-save-status" role="status">${state.status==='complete'?'已完成并保存。':state.filled?'已恢复草稿。':'尚未填写。'}</p></div></details>`;
}
function workbookVarieties(kind){const white=kind==='white',names=workbookData[kind],counts=workbookVarietyCounts(kind);return `<section class="wb-varieties" data-variety-group="${kind}"><header class="wb-variety-heading"><h2>${white?'白葡萄品种':'红葡萄品种'} · ${names.length} 项</h2><span class="wb-group-progress">已完成 ${counts.complete} / ${counts.total} · 草稿 ${counts.draft}</span></header><p class="fine">点击展开。同一品种的表现随产区与酿造方式变化。</p><div class="wb-variety-tools"><label><span class="sr-only">查找${white?'白':'红'}葡萄品种</span><input type="search" class="wb-variety-search" aria-label="查找${white?'白':'红'}葡萄品种" placeholder="输入中文或英文品种名…"></label><label><span class="sr-only">筛选${white?'白':'红'}葡萄填写状态</span><select class="wb-variety-filter" aria-label="筛选${white?'白':'红'}葡萄填写状态"><option value="all">全部状态</option><option value="empty">未填写</option><option value="draft">草稿</option><option value="complete">已完成</option></select></label><button class="wb-bulk-control" type="button" data-variety-expand="true">全部展开</button><button class="wb-bulk-control" type="button" data-variety-expand="false">全部收起</button></div><p class="wb-filter-result" aria-live="polite">显示 ${names.length} 项</p><div class="wb-variety-grid">${names.map((_,i)=>workbookVarietyCard(kind,i)).join('')}</div><p class="wb-variety-empty" hidden>无匹配品种，请调整搜索或筛选。</p></section>`}
function workbookVarietyTotals(){const a=workbookVarietyCounts('white'),b=workbookVarietyCounts('red');return `已完成 ${a.complete+b.complete} / 26 · 草稿 ${a.draft+b.draft}`}
function workbookVarietyMatches(name,state,query,filter){const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return normalize(name).includes(normalize(query.trim()))&&(filter==='all'||state===filter)}
function bindWorkbook(){
 const groups=[...document.querySelectorAll('[data-variety-group]')];if(!groups.length)return;
 const valuesOf=card=>[...card.querySelectorAll('[data-variety-note]')].map(el=>el.value);
 const updateCard=card=>{const state=workbookVarietyState(card.dataset.kind,Number(card.dataset.index),valuesOf(card));card.dataset.status=state.status;card.querySelector('.wb-variety-count').textContent=`已填 ${state.filled} / 4`;card.querySelector('.wb-variety-status').textContent=state.label;return state};
 const updateProgress=()=>{let complete=0,draft=0;for(const group of groups){const states=[...group.querySelectorAll('[data-variety-id]')].map(card=>workbookVarietyState(card.dataset.kind,Number(card.dataset.index),valuesOf(card)));const c={complete:states.filter(s=>s.status==='complete').length,draft:states.filter(s=>s.status==='draft').length,total:states.length};complete+=c.complete;draft+=c.draft;group.querySelector('.wb-group-progress').textContent=`已完成 ${c.complete} / ${c.total} · 草稿 ${c.draft}`;}const total=document.querySelector('[data-variety-total]');if(total)total.textContent=`已完成 ${complete} / 26 · 草稿 ${draft}`};
 const filterGroup=group=>{const query=group.querySelector('.wb-variety-search').value,filter=group.querySelector('.wb-variety-filter').value;let shown=0;for(const card of group.querySelectorAll('[data-variety-id]')){card.hidden=!workbookVarietyMatches(workbookData[card.dataset.kind][Number(card.dataset.index)],card.dataset.status,query,filter);if(!card.hidden)shown++;}group.querySelector('.wb-variety-empty').hidden=shown!==0;group.querySelector('.wb-filter-result').textContent=`显示 ${shown} 项`;};
 const persist=(card,complete)=>{const ok=saveWorkbookVariety(card.dataset.kind,Number(card.dataset.index),valuesOf(card),complete);const status=card.querySelector('.wb-save-status');status.classList.toggle('save-error',!ok);status.dataset.state=ok?'saved':'error';status.textContent=ok?(complete?(valuesOf(card).every(v=>v.trim())?'已完成并保存。':'草稿已保存，填完四项后可标记完成。'):'草稿已自动保存。'):'保存失败，请复制答案备份后重试。';updateCard(card);updateProgress();return ok;};
 const focusSummary=card=>{card.querySelector('summary').focus();card.scrollIntoView({behavior:'smooth',block:'nearest'})};
 for(const group of groups){
  group.querySelector('.wb-variety-search').addEventListener('input',()=>filterGroup(group));
  group.querySelector('.wb-variety-filter').addEventListener('change',()=>filterGroup(group));
  for(const button of group.querySelectorAll('[data-variety-expand]'))button.addEventListener('click',()=>{for(const card of group.querySelectorAll('[data-variety-id]'))if(!card.hidden)card.open=button.dataset.varietyExpand==='true';});
  for(const card of group.querySelectorAll('[data-variety-id]')){
   for(const field of card.querySelectorAll('[data-variety-note]'))field.addEventListener('input',()=>persist(card,false));
   for(const button of card.querySelectorAll('[data-variety-save]'))button.addEventListener('click',()=>{
    if(!persist(card,true))return;
    card.open=false;filterGroup(group);
    const cards=groups.flatMap(g=>[...g.querySelectorAll('[data-variety-id]')]);const after=cards.slice(cards.indexOf(card)+1);const next=after.find(c=>!c.hidden);
    if(button.dataset.varietySave==='next'&&next){next.open=true;focusSummary(next);next.querySelector('[data-variety-note]')?.focus();}
    else if(!card.hidden)focusSummary(card);else if(next)focusSummary(next);else group.querySelector('.wb-variety-filter').focus();
    const note=document.querySelector('#note-status');if(note)note.textContent='已保存。';
    toast(workbookVarietyState(card.dataset.kind,Number(card.dataset.index)).status==='complete'?'已完成并保存。':'草稿已保存。');
   });
  }
 }
}
function workbookView(which){const session=which==='2'?2:1,qs=workbookData.questions.filter(q=>q[0]===session);return `<main id="main" class="wrap wb-page"><a class="back" href="${session===1?'#quiz':'#session2quiz'}">← Session ${session} 自测</a><div class="page-intro"><div class="eyebrow">WORKBOOK / SESSION ${session}</div><h1 class="page-title">练习册</h1><p>Session ${session} 练习册 · ${qs.length} 道简答题 · 共 ${qs.reduce((n,q)=>n+q[2],0)} 分${session===1?' · 另含26个品种填写表':''}</p><nav class="wb-tabs" aria-label="选择练习册"><a href="#workbook/1" ${session===1?'aria-current="page"':''}>Session 1 · 葡萄藤与环境</a><a href="#workbook/2" ${session===2?'aria-current="page"':''}>Session 2 · 葡萄园管理</a></nav></div><aside class="callout"><strong>作答说明</strong><p>暂无机构参考答案；复习提示供自查，不自动评分。已收录本次提供的简答页与品种表。</p><small id="note-status" role="status">自动保存到当前浏览器，不跨设备同步。</small></aside>${session===1?'<p class="wb-shortcuts"><a href="#varieties" data-book-jump="varieties">跳到品种练习 · 26 项 ↓</a></p>':''}${qs.map(workbookQuestion).join('')}${session===1?'<section class="wb-variety-intro" id="varieties"><h2>品种练习</h2><p data-variety-total aria-live="polite">'+workbookVarietyTotals()+'</p><p class="fine">自动保存草稿；填完四项并保存后，记为已完成。</p></section>'+workbookVarieties('white')+workbookVarieties('red'):''}</main>`}
